#!/usr/bin/env python3
"""Compare Frosty's probe irradiance shader against native wave64 on two GPUs."""
import argparse
import json
import math
import os
from pathlib import Path
import shutil
import struct
import subprocess
import sys
from tempfile import TemporaryDirectory

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from build import Toolchain
from check_frosty_shaders import containers, decoder, decompress, global_archive
from project_tuxbox.host import Host
from project_tuxbox.inspect import digest
from project_tuxbox.shader_prep import compiler_tools


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("mount", type=Path)
    parser.add_argument("--prefix-amd", type=Path, required=True)
    parser.add_argument("--prefix-nvidia", type=Path, required=True)
    parser.add_argument("--proton", type=Path, required=True)
    parser.add_argument("--amd-vulkan", type=Path)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    translator, dxc, dxv = compiler_tools()
    cases = ["active", "width1", "width2", "width3", "partial", "quarter", "empty", "rejected"]
    with TemporaryDirectory(prefix="tuxbox-irradiance-") as directory:
        work = Path(directory)
        payload, entries = global_archive(args.mount)
        source = next(containers(decompress(payload, entries[475], decoder())))[1]
        (work / "native.cso").write_bytes(source)
        hlsl = work / "shader.hlsl"
        subprocess.run([translator, work / "native.cso", "--hlsl-out", hlsl], check=True)
        text = hlsl.read_text()
        begin = text.index("groupshared uint page_bits")
        end = text.index("// Generated by", begin)
        reference = text[:begin] + """
uint2 tb_page_ballot(uint tid, bool vote) { return WaveActiveBallot(vote).xy; }
uint tb_page_read(uint tid, uint value, uint lane) { return WaveReadLaneAt(value, lane & 63u); }
""" + text[end:]
        reference = reference.replace("[numthreads(8, 8, 1)]", "[WaveSize(64)]\n[numthreads(8, 8, 1)]", 1)
        sampled = text
        sample = "float4 t13 = tex2.SampleLevel(samp0, float2(asfloat(v7), asfloat(v8)), 0.0);"
        result = "if (exec_lo & 1u) uav0[uint2(v11, v12)] = float4(asfloat(v4), asfloat(v5), asfloat(v6), 0.0);"
        fallback = "if (exec_lo & 1u) uav0[uint2(v7, v8)] = float4(asfloat(v4), asfloat(v5), asfloat(v6), 0.0);"
        if any(sampled.count(part) != 1 for part in (sample, result, fallback)):
            raise ValueError("unexpected irradiance sample layout")
        sampled = sampled.replace(sample, sample + "\nif (exec_lo & 1u) uav0[uint2(v0, v1)] = t13;")
        sampled = sampled.replace(result, "").replace(fallback, "")
        native_hlsl = work / "native-wave.hlsl"
        native_hlsl.write_text(reference)
        sample_hlsl = work / "sample.hlsl"
        sample_hlsl.write_text(sampled)
        for name, program, profile in [
            ("portable.cso", hlsl, "cs_6_0"),
            ("reference.cso", native_hlsl, "cs_6_6"),
            ("sample.cso", sample_hlsl, "cs_6_0"),
        ]:
            subprocess.run([dxc, "-T", profile, "-E", "main", "-Fo", work / name, program], check=True)
            subprocess.run([dxv, work / name], check=True, stdout=subprocess.DEVNULL)
        toolchain = Toolchain()
        obj = toolchain.compile(ROOT / "tools/reference/irradiance/guest.cpp", work,
                                f"/I{ROOT / 'runtime/d3d12'}")
        exe = work / "probe.exe"
        toolchain.link(exe, obj, "d3d12.lib", "dxgi.lib", "kernel32.lib")
        reference_outputs = {}
        sampled_outputs = {}
        results = {}
        saved_env = os.environ.copy()
        try:
            for name, adapter, prefix, shader in [
                ("native_amd", "AMD", args.prefix_amd, "reference.cso"),
                ("portable_amd", "AMD", args.prefix_amd, "portable.cso"),
                ("portable_nvidia", "NVIDIA", args.prefix_nvidia, "portable.cso"),
                ("sample_amd", "AMD", args.prefix_amd, "sample.cso"),
                ("sample_nvidia", "NVIDIA", args.prefix_nvidia, "sample.cso"),
            ]:
                os.environ["VKD3D_FILTER_DEVICE_NAME"] = adapter
                os.environ["DXVK_FILTER_DEVICE_NAME"] = adapter
                if adapter == "AMD" and args.amd_vulkan:
                    os.environ["VK_DRIVER_FILES"] = str(args.amd_vulkan)
                elif adapter == "NVIDIA":
                    os.environ.pop("VK_DRIVER_FILES", None)
                shutil.copyfile(work / shader, work / "shader.cso")
                host = Host(None, str(args.proton), prefix)
                run = host.run(exe, [], timeout=60, capture=True)
                info = (work / "result.txt").read_text(errors="replace")
                if run.returncode:
                    raise RuntimeError(f"{name} exited {run.returncode}: {info}")
                outputs = {case: struct.unpack("<512f", (work / (case + ".bin")).read_bytes())
                           for case in cases}
                if name.startswith("sample_"):
                    sampled_outputs[name] = struct.unpack("<512f", (work / "sampled.bin").read_bytes())
                elif name == "native_amd":
                    reference_outputs = outputs
                    if not any(v > 0 for v in outputs["active"]):
                        raise ValueError("active probe produced no irradiance")
                else:
                    for case in cases:
                        if any(not math.isclose(a, b, rel_tol=1e-6, abs_tol=1e-6)
                               for a, b in zip(reference_outputs[case], outputs[case], strict=True)):
                            raise ValueError(f"{name} differs from native wave64 in {case}")
                results[name] = {"adapter": info.strip(), "cases": len(cases),
                                 "compared_words_per_case": 512}
        finally:
            os.environ.clear()
            os.environ.update(saved_env)
        receipt = {
            "scope": "Packaged global 475 probe irradiance; portable wave64 versus native Radeon wave64",
            "source_sha256": digest(work / "native.cso"),
            "compiler_sha256": digest(Path(translator)),
            "cases": ["8x8 active probe", "1x1 to 5x5 partial wave",
                      "zero counter", "rejected probe"],
            "tolerance": 1e-6,
            "runs": results,
            "point_sample_boundary": {
                "scope": "Width 3, gradient texture, direct capture after SampleLevel",
                "different_words": sum(a != b for a, b in zip(
                    sampled_outputs["sample_amd"], sampled_outputs["sample_nvidia"], strict=True)),
            },
        }
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(json.dumps(receipt, indent=2) + "\n")
        print(json.dumps(receipt, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
